using System;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Linq;using System.Windows.Forms;using System.Web.Script.Serialization;using NetScope;
class UiRegression {
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
 [STAThread]static int Main(string[] args){var root=Path.GetFullPath(args[0]);var data=Path.Combine(root,"synthetic-regression");Directory.CreateDirectory(data);try{Application.EnableVisualStyles();using(var c=new AppController(data)){var settings=c.Settings;settings.AutoMonitor=false;settings.AiAutoEnabled=false;settings.MaxAiCallsPerDay=0;settings.CodexPath=Path.Combine(data,"missing.exe");c.SaveSettings(settings);var local=new LocalSample{At=DateTime.UtcNow,TrafficAdapterName="Synthetic Wi-Fi",TrafficAdapterId="test-wifi"};typeof(AppController).GetField("local",flags).SetValue(c,local);var rows=new List<DeviceInfo>{D("192.168.50.5","AA-22-33-44-55-66","本机接口；接口 6","本机"),D("192.168.50.1","02-11-22-33-44-55","Windows 邻居缓存；接口 6","Reachable"),D("192.168.50.200","00-00-00-00-00-00","Windows 邻居缓存；接口 6","Unreachable"),D("192.168.50.201","未知","用户触发的有限 ICMP 回应；接口 6","本次ICMP回应（不代表主人已确认）"),D("192.168.50.202","10-11-22-33-44-55","Windows 邻居缓存；接口 6","Stale"),D("192.168.50.202","未知","用户触发的有限 ICMP 回应；接口 6","本次ICMP回应（不代表主人已确认）"),D("192.168.50.203","10-11-22-33-44-55","Windows 邻居缓存；接口 6","Stale"),D("198.18.0.2","未知","Windows 邻居缓存；接口 60","Reachable"),D("224.0.0.251","01-00-5E-00-00-FB","Windows 邻居缓存；接口 6","Permanent")};typeof(AppController).GetField("devices",flags).SetValue(c,rows);using(var f=new MainForm(c)){typeof(MainForm).GetMethod("SelectPage",flags).Invoke(f,new object[]{4});InjectTopology(f);var physical=(FlowLayoutPanel)typeof(MainForm).GetField("deviceCards",flags).GetValue(f);var vpn=(FlowLayoutPanel)typeof(MainForm).GetField("virtualDeviceCards",flags).GetValue(f);var grid=(DataGridView)typeof(MainForm).GetField("deviceGrid",flags).GetValue(f);Check(physical.Controls.Count==4,"Expected own computer/router/ICMP/merged; actual="+physical.Controls.Count+"; cards="+String.Join("|",physical.Controls.Cast<FriendlyTile>().Select(x=>x.NameLabel.Text).ToArray())+"; vpn="+vpn.Controls.Count);Check(vpn.Controls.Count==1,"VPN record must be in separate section");Check(grid.Rows.Count==rows.Count,"Raw rows must remain complete");var pending=typeof(MainForm).GetMethod("IsPendingDeviceAddress",flags);Check((bool)pending.Invoke(f,new object[]{rows[2]}),"Unknown-MAC failure must be pending");Check(!(bool)pending.Invoke(f,new object[]{rows[3]}),"Confirmed ICMP without MAC must be retained");Check(physical.Controls.Cast<FriendlyTile>().Count(x=>x.NameLabel.Text.Contains("有回应"))==1,"Same interface/IP must not create duplicate responder tile");var answers=All(f).OfType<InspectionRow>().ToList();Check(answers.Count==6,"Six checklist rows must remain");var answer=answers[0];answer.ToggleExpanded();Check(answer.Expanded&&answer.Height==140,"Expanded explanation must get full height");answer.ToggleExpanded();Check(!answer.Expanded&&answer.Height==78,"Collapse must restore compact row");Check(!c.IsDeviceDiscovering&&c.AiCallsToday==0&&c.CurrentFrame==null,"No online workflow may start during regression");using(var file=File.Create(Path.Combine(root,"NetScope.ico")))f.Icon.Save(file);}}File.WriteAllText(Path.Combine(root,"ui-regression-result.txt"),"PASS "+checks+" assertions. Synthetic inputs used only for behavior checks, not screenshots. No active discovery, model, HTTP probes or name lookup.");Console.WriteLine("RESULT "+checks+" UI behavior checks passed; synthetic only.");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"ui-regression-error.txt"),ex.ToString());Console.WriteLine(ex);return 1;}}
 static void InjectTopology(MainForm f){var topology=typeof(MainForm).GetField("deviceTopology",flags).GetValue(f);var entryType=typeof(DeviceTopology).GetNestedType("Entry",BindingFlags.NonPublic);var entries=(System.Collections.IDictionary)typeof(DeviceTopology).GetField("entries",flags).GetValue(topology);entries.Clear();Action<int,string,bool,string> add=delegate(int index,string name,bool isVirtual,string gateway){var entry=Activator.CreateInstance(entryType,true);entryType.GetField("Name").SetValue(entry,name);entryType.GetField("Virtual").SetValue(entry,isVirtual);entryType.GetField("Up").SetValue(entry,true);entryType.GetField("Physical").SetValue(entry,!isVirtual);entryType.GetField("Gateways").SetValue(entry,new List<System.Net.IPAddress>{System.Net.IPAddress.Parse(gateway)});entries[index]=entry;};add(6,"Synthetic Wi-Fi",false,"192.168.50.1");add(60,"Synthetic VPN",true,"198.18.0.2");typeof(MainForm).GetField("lastDeviceCardsKey",flags).SetValue(f,"");typeof(MainForm).GetMethod("RefreshDevices",flags).Invoke(f,null);}
 static DeviceInfo D(string ip,string mac,string source,string state){return new DeviceInfo{Ip=ip,Mac=mac,Name="未知",NameSource="未识别",Hint="未知",Source=source,State=state,ObservedAt=DateTime.UtcNow};}
 static IEnumerable<Control> All(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in All(x))yield return y;}}
}
